<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sorting Algorithm Visualizer</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: #0f172a;
      color: #f8fafc;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .card {
      background-color: #1e293b;
      border: 1px solid #334155;
      border-radius: 12px;
      padding: 24px;
      width: 100%;
      max-width: 800px;
      box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5);
      display: flex;
      flex-direction: column;
      gap: 20px;
    }

    .header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-bottom: 1px solid #334155;
      padding-bottom: 16px;
    }

    h1 {
      font-size: 1.5rem;
      font-weight: 600;
      color: #f1f5f9;
    }

    .status-badge {
      font-size: 0.875rem;
      font-weight: 500;
      padding: 4px 12px;
      border-radius: 9999px;
      background-color: #334155;
      color: #94a3b8;
    }

    .status-badge.sorting {
      background-color: #0284c7;
      color: #e0f2fe;
    }

    .status-badge.sorted {
      background-color: #15803d;
      color: #dcfce7;
    }

    #bars {
      display: flex;
      align-items: flex-end;
      justify-content: center;
      gap: 3px;
      height: 320px;
      width: 100%;
      background-color: #0f172a;
      border: 1px solid #334155;
      border-radius: 8px;
      padding: 16px 12px;
    }

    .bar {
      flex: 1;
      background-color: #3b82f6;
      border-radius: 3px 3px 0 0;
      transition: height 0.05s ease, background-color 0.05s ease;
      min-width: 2px;
    }

    .bar.active {
      background-color: #f59e0b;
    }

    .bar.sorted {
      background-color: #10b981;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      align-items: center;
      justify-content: space-between;
    }

    .button-group {
      display: flex;
      gap: 10px;
    }

    button {
      font-family: inherit;
      font-size: 0.9rem;
      font-weight: 600;
      padding: 10px 18px;
      border-radius: 6px;
      border: none;
      cursor: pointer;
      transition: background-color 0.15s ease, opacity 0.15s ease;
    }

    button:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    #sort {
      background-color: #22c55e;
      color: #052e16;
    }

    #sort:hover:not(:disabled) {
      background-color: #16a34a;
    }

    #shuffle {
      background-color: #3b82f6;
      color: #1e3a8a;
    }

    #shuffle:hover:not(:disabled) {
      background-color: #2563eb;
    }

    #reset {
      background-color: #475569;
      color: #f8fafc;
    }

    #reset:hover:not(:disabled) {
      background-color: #334155;
    }

    .speed-control {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 0.85rem;
      color: #94a3b8;
    }

    input[type="range"] {
      accent-color: #3b82f6;
      cursor: pointer;
    }
  </style>
</head>
<body>

  <div class="card">
    <div class="header">
      <h1>Sorting Algorithm Visualizer</h1>
      <span id="status" class="status-badge">Ready</span>
    </div>

    <div id="bars"></div>

    <div class="controls">
      <div class="button-group">
        <button id="sort">Sort</button>
        <button id="shuffle">Shuffle</button>
        <button id="reset">Reset</button>
      </div>

      <div class="speed-control">
        <label for="speed">Speed:</label>
        <input type="range" id="speed" min="1" max="100" value="70">
      </div>
    </div>
  </div>

  <script>
    (function () {
      let arr = [];
      let initialArr = [];
      let i = 0;
      let j = 0;
      let isAnimRunning = false;
      let animTimeoutId = null;

      const barsContainer = document.getElementById('bars');
      const statusBadge = document.getElementById('status');
      const sortBtn = document.getElementById('sort');
      const shuffleBtn = document.getElementById('shuffle');
      const resetBtn = document.getElementById('reset');
      const speedSlider = document.getElementById('speed');

      function isSorted(a) {
        if (!a || a.length <= 1) return true;
        for (let idx = 0; idx < a.length - 1; idx++) {
          if (a[idx] > a[idx + 1]) return false;
        }
        return true;
      }

      function redraw(activeIndices = [], complete = false) {
        barsContainer.innerHTML = '';
        if (!arr || arr.length === 0) return;

        const maxVal = Math.max(...arr, 1);
        const done = complete || isSorted(arr);

        arr.forEach((val, idx) => {
          const bar = document.createElement('div');
          bar.className = 'bar';

          let pct = (val / maxVal) * 100;
          pct = Math.max(pct, 4);
          bar.style.height = `${pct}%`;
          bar.setAttribute('title', `Value: ${val}`);

          if (done) {
            bar.classList.add('sorted');
          } else if (activeIndices.includes(idx)) {
            bar.classList.add('active');
          }

          barsContainer.appendChild(bar);
        });

        updateUIState(done);
      }

      function updateUIState(done) {
        if (isAnimRunning) {
          statusBadge.textContent = 'Sorting...';
          statusBadge.className = 'status-badge sorting';
        } else if (done) {
          statusBadge.textContent = 'Sorted!';
          statusBadge.className = 'status-badge sorted';
        } else {
          statusBadge.textContent = 'Ready';
          statusBadge.className = 'status-badge';
        }
      }

      function stopAnimation() {
        if (animTimeoutId) {
          clearTimeout(animTimeoutId);
          animTimeoutId = null;
        }
        isAnimRunning = false;
      }

      // Public API on window.viz
      window.viz = {
        array: function () {
          return [...arr];
        },

        setArray: function (a) {
          stopAnimation();
          arr = Array.from(a).map(Number);
          initialArr = [...arr];
          i = 0;
          j = 0;
          redraw();
        },

        sortStep: function () {
          if (isSorted(arr)) {
            redraw([], true);
            return true;
          }

          if (arr.length <= 1) {
            redraw([], true);
            return true;
          }

          if (arr[j] > arr[j + 1]) {
            const temp = arr[j];
            arr[j] = arr[j + 1];
            arr[j + 1] = temp;
          }

          const activeIndices = [j, j + 1];

          j++;
          if (j >= arr.length - 1 - i) {
            j = 0;
            i++;
            if (i >= arr.length - 1) {
              i = 0;
            }
          }

          const done = isSorted(arr);
          redraw(done ? [] : activeIndices, done);
          return done;
        },

        sorted: function () {
          return isSorted(arr);
        }
      };

      function startSortAnimation() {
        if (isAnimRunning || window.viz.sorted()) return;
        isAnimRunning = true;

        function step() {
          const done = window.viz.sortStep();
          if (!done && isAnimRunning) {
            const speedVal = parseInt(speedSlider.value, 10);
            const delay = Math.max(1, 105 - speedVal);
            animTimeoutId = setTimeout(step, delay);
          } else {
            stopAnimation();
            redraw([], window.viz.sorted());
          }
        }

        step();
      }

      function shuffleArray() {
        stopAnimation();
        for (let idx = arr.length - 1; idx > 0; idx--) {
          const r = Math.floor(Math.random() * (idx + 1));
          [arr[idx], arr[r]] = [arr[r], arr[idx]];
        }
        initialArr = [...arr];
        i = 0;
        j = 0;
        redraw();
      }

      function resetArray() {
        stopAnimation();
        arr = [...initialArr];
        i = 0;
        j = 0;
        redraw();
      }

      sortBtn.addEventListener('click', startSortAnimation);
      shuffleBtn.addEventListener('click', shuffleArray);
      resetBtn.addEventListener('click', resetArray);

      // Default initialization
      const defaultArray = [28, 12, 45, 8, 33, 19, 50, 5, 38, 22, 41, 15, 30, 3, 48, 11, 36, 17, 25, 42];
      window.viz.setArray(defaultArray);
    })();
  </script>
</body>
</html>
